@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderRepository orderRepository;
    private final InventoryClient inventoryClient;
    private final PaymentClient paymentClient;

    public OrderController(OrderRepository orderRepository, InventoryClient inventoryClient, PaymentClient paymentClient) {
        this.orderRepository = orderRepository;
        this.inventoryClient = inventoryClient;
        this.paymentClient = paymentClient;
    }

    @PostMapping
    @Transactional
    public ResponseEntity<Order> createOrder(@RequestBody OrderRequest request) {
        // In a monolith, inventory check and payment processing happen within the same local transaction and database session.
        // In microservices, these calls traverse the network and require explicit compensation logic if one fails.
        inventoryClient.reserveStock(request.getProductId(), request.getQuantity());
        paymentClient.processPayment(request.getUserId(), request.getAmount());

        Order order = orderRepository.save(new Order(request));
        return ResponseEntity.status(HttpStatus.CREATED).body(order);
    }
}
